SET @inventory_permission_id = (SELECT COALESCE(MAX(id),0) FROM eam_sys_role_menu_permission);
INSERT INTO eam_sys_role_menu_permission(id,tenant_id,role_id,menu_key,actions_json,data_scopes_json,org_ids_json) SELECT (@inventory_permission_id := @inventory_permission_id + 1),p.tenant_id,p.role_id,'inventoryMaterial',JSON_ARRAY(IF(JSON_CONTAINS(p.actions_json,JSON_QUOTE('查看')),'查看',NULL),IF(JSON_CONTAINS(p.actions_json,JSON_QUOTE('新增')),'新增',NULL),IF(JSON_CONTAINS(p.actions_json,JSON_QUOTE('编辑')),'编辑',NULL),IF(JSON_CONTAINS(p.actions_json,JSON_QUOTE('导入')),'导入',NULL),IF(JSON_CONTAINS(p.actions_json,JSON_QUOTE('导出')),'导出',NULL)),JSON_ARRAY('all'),JSON_ARRAY() FROM eam_sys_role_menu_permission p WHERE p.menu_key='inventory' AND NOT EXISTS(SELECT 1 FROM eam_sys_role_menu_permission c WHERE c.tenant_id=p.tenant_id AND c.role_id=p.role_id AND c.menu_key='inventoryMaterial');
